@startuml

class Aircraft {
  + name
  + type
  + year_of_manufacture
  + next_inspection_date
}

class PassengerAircraft extends Aircraft {
  + number_of_seats
}

class SeatCategory {
  + designation
  + offers_entertainment
  + number_of_seats
}

class Flight {
  + flight_number
  + date
}

class Passenger {
  + name
  + passport_number
}

class Ticket {
  + ticket_number
  + price
  + upgrade_desired
}

class Airline {
  + name
}

class FlightAttendant {
  + name
  + date_of_employment
  + is_chief_stewardess
}

class Pilot {
  + name
  + date_of_employment
  + license
}

class Airport {
  + name
  + address
  + number_of_runways
}

Aircraft "0..*" -- "1" Airline : belongs to
Aircraft "1" -- "*" Flight : performs
PassengerAircraft "1" *-- "*" SeatCategory : has
Passenger "1" -- "*" Ticket : holds
Flight "1" *-- "*" Ticket : issues
Ticket "*" -- "1" SeatCategory : for
Flight "*" -- "1..*" FlightAttendant : staffed by
Flight -- "1" Pilot : captain
Flight -- "1..2" Pilot : co-pilot
Flight "*" -- "1" Airport : departs from
Flight "*" -- "1" Airport : arrives at
Aircraft "0..1" -- "1" Airport : home airport

@enduml

